        {
            if (DispatcherQueue.HasThreadAccess)
            {
                LogFromUIThread(message, level);
            }
            else
            {
                DispatcherQueue.TryEnqueue(() =>
                {
                    LogFromUIThread(message, level);
                });
            }
        }

